-- ************************************** BILLING.BILL
CREATE TABLE BILLING.BILL
(
 BILL_ID             varchar(30) NOT NULL COMMENT 'Primary key for bill/invoice record.',
 ADDRESS             string NOT NULL,
 SERVICE_LOCATION_ID varchar(20) NOT NULL COMMENT 'Foreign key to Service Location.',
 BILLING_PERIOD_ID   int NOT NULL COMMENT 'Foreign key to Billing Period.',
 BILL_DATE           date NOT NULL COMMENT 'Date when bill was generated.',
 DUE_DATE            date NOT NULL COMMENT 'Due date for payment.',
 SUBTOTAL_AMOUNT     decimal(12,2) NOT NULL COMMENT 'Total charges before taxes.',
 TAX_AMOUNT          decimal(12,2) COMMENT 'Total tax amount.',
 TOTAL_AMOUNT        decimal(12,2) NOT NULL COMMENT 'Total bill amount due.',
 AMOUNT_PAID         decimal(12,2) NOT NULL COMMENT 'Amount paid to date on this bill.',
 BALANCE_DUE         decimal(12,2) COMMENT 'Remaining balance unpaid on this bill.',
 BILL_STATUS         varchar(20) NOT NULL COMMENT 'Current status of bill (Draft, Issued, Paid, Overdue, etc).',
 NOTES               varchar(500) COMMENT 'Detailed comments or notes on the bill.',

 CONSTRAINT PK_1 PRIMARY KEY ( BILL_ID ),
 CONSTRAINT FK_1 FOREIGN KEY ( SERVICE_LOCATION_ID ) REFERENCES CUSTOMER.SERVICE_LOCATION ( SERVICE_LOCATION_ID ),
 CONSTRAINT FK_2 FOREIGN KEY ( BILLING_PERIOD_ID ) REFERENCES BILLING.BILLING_PERIOD ( BILLING_PERIOD_ID )
)
COMMENT = 'Main billing transaction table tracking individual customer bills and payment status.';
